bool guard = count > 0 && items != null; // short-circuit: items not checked if count <= 0

string? cached = redisGet; // may be null
string json = cached ?? "{}";
int? ttl = cacheEntry?.TtlSeconds;

// C# 14: assign only if receiver is non-null; RHS skipped when null
cacheEntry?.LastAccessUtc = DateTime.UtcNow;

string? name = null;
name ??= "default";     // assigns "default" because name is null

CacheEntry? entry = GetEntry();
entry?.HitCount += 1;   // C# 14: increment only if entry is not null

